                  "Formula 2: V = W / Q (V in Volts, W in Joules, Q in Coulombs).",
                  "Combined Formula: W = V * Q = V * I * t.",
                  "Ammeter symbol: (A) with positive (+) red and negative (-) black terminals, connected in Series.",
                  "Voltmeter symbol: (V), connected in Parallel across a load (for V) or across a battery in an open circuit (for EMF)."
