              "vocabulary": [
                {
                  "word": "Natural Selection",
                  "meaning": "Process by which organisms with favorable environmental adaptations survive, reproduce, and pass traits to future generations.",
                  "opposite": "Artificial Selection",
                  "plural": "—"
                },
                {
                  "word": "Survival of the Fittest",
                  "meaning": "Principle that individuals best suited to their specific environment survive and reproduce most successfully.",
                  "opposite": "Extinction",
                  "plural": "—"
                },
                {
                  "word": "Adaptation",
                  "meaning": "An inherited structural, behavioral, or physiological feature that improves an organism's chance of survival and reproduction.",
                  "opposite": "Maladaptation",
                  "plural": "Adaptations"
                },
                {
                  "word": "Camouflage",
                  "meaning": "An adaptation allowing organisms to blend into their surroundings to avoid predators or catch prey.",
                  "opposite": "Conspicuousness",
                  "plural": "—"
                },
                {
                  "word": "Artificial Selection",
                  "meaning": "Human-directed breeding of plants and animals to select, reinforce, and propagate desirable traits.",
                  "opposite": "Natural Selection",
                  "plural": "—"
                },
                {
                  "word": "Selective Breeding",
                  "meaning": "The intentional mating of two organisms with specific desirable characteristics to produce superior offspring.",
                  "opposite": "Random Mating",
                  "plural": "—"
                },
                {
                  "word": "Genetic Variation",
                  "meaning": "Differences in alleles and DNA sequences among individuals within a population.",
                  "opposite": "Genetic Clones",
                  "plural": "Genetic Variations"
                },
                {
                  "word": "Antibiotic Resistance",
                  "meaning": "Ability of bacteria to survive exposure to antibiotics due to evolutionary selection of resistant strains.",
                  "opposite": "Antibiotic Sensitivity",
                  "plural": "—"
                }
              ],
